                            testStage,
                            latestFreqResult,
                            latestSongResult,
                            latestFqcResult,
                            configStatus,
                            currentTimestamp,
                            currentTimestamp,
                            null,
                            "SYSTEM",
                            "Migrated from existing test on $currentTimestamp",
                            1,
                            0L
                        ))

