class FQCRepository(
    private val database: AppDatabase,
    private val supabaseService: SupabaseFrequencyTestService = SupabaseFrequencyTestService(),
    private val supabaseSongTestService: com.example.fqcapp.supabase.SupabaseSongTestService = com.example.fqcapp.supabase.SupabaseSongTestService()
) {
    private val TAG = "FQCRepository"
    private val supabaseScope = CoroutineScope(Dispatchers.IO)

    // Operator operations
