        // Save to local database first
        val operatorId = database.operatorDao().insert(operator)

        // NOTE: Supabase operator sync disabled - operators are managed locally via Google Sheets sync
        // The 34 operators from Google Sheets are sufficient for app operation
        // Uncomment below if Supabase operator sync is needed in the future:
        /*
