                        .padding(vertical = 16.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Checkbox(
                        checked = loopSweep,
                        onCheckedChange = { 
                            android.util.Log.d("FrequencyGenerator", "Loop checkbox changed: $it")
                            loopSweep = it
