@Composable
fun DatabaseSection(
    title: String,
    count: Int,
    isExpanded: Boolean,
    onExpandToggle: () -> Unit,
    surfaceColor: Color,
    textColor: Color,
    accentColor: Color,
    content: @Composable () -> Unit
