                    fallback
                }
                android.util.Log.d("FrequencyGenerator", "   ✅ Session entry timestamp: $sessionEntryTimestamp")

                // Calculate total time spent and format as HH:MM:SS
                val totalTimeSpentSeconds = durationMs / 1000
                val hours = totalTimeSpentSeconds / 3600
                val minutes = (totalTimeSpentSeconds % 3600) / 60
                val seconds = totalTimeSpentSeconds % 60
                val totalTimeSpentFormatted = String.format("%02d:%02d:%02d", hours, minutes, seconds)

                android.util.Log.d("FrequencyGenerator", "⏱️ Entry: $sessionEntryTimestamp, Exit: $endTimeFormatted, Duration: $totalTimeSpentFormatted")

