                android.util.Log.d("FrequencyGenerator", "📋 [ACTION] Creating FrequencyTest entity...")
                android.util.Log.d("FrequencyGenerator", "   📤 [DATA] Test data prepared:")
                android.util.Log.d("FrequencyGenerator", "      - serialNumber: $serialNumber")
