                    } catch (e: Exception) {
                        android.util.Log.e("FrequencyGenerator", "❌ [MILESTONE_CALL] Error updating milestone", e)
                        e.printStackTrace()
                    }
                } catch (e: Exception) {
                    android.util.Log.e("FrequencyGenerator", "❌ Failed to save frequency test", e)
                }

                // Complete the test session
                currentTestSessionId?.let { sessionId ->
