object Routes {
    const val LANDING = "landing"
    const val SCANNER = "scanner"
    const val REVIEW = "review"
    const val DATABASE_VIEWER = "database_viewer"
    const val TEST_SONGS = "test_songs"
    const val FREQ_GEN = "frequency_generator"
    const val FQC_REVIEW = "fqc_review"
    const val DEVICE_CONFIG = "device_config"
    const val DEVICE_INFORMATION = "device_information"
    const val DRIVER_PAIRING = "driver_pairing"
    const val CHANGED_PART = "changed_part"
    const val OPERATOR_SELECTION = "operator_selection"

    // Helper function to build operator selection route with destination
    fun operatorSelection(destination: String): String {
        return "$OPERATOR_SELECTION/$destination"
    }
}

@Composable
fun AppNav(activity: ComponentActivity, operatorName: String, permissionHandler: PermissionHandler, onLogout: () -> Unit) {
    val nav = rememberNavController()
    val context = LocalContext.current
    val database = remember { AppDatabase.getDatabase(context) }
    val repository = remember { FQCRepository(database) }
    val prefsManager = remember { PreferencesManager(context) }
    val scope = rememberCoroutineScope()
    val eligibilityService = remember { DeviceEligibilityService(repository, database) }
    // MAC ID cache manager for reverse lookup (MAC ID -> Serial Number)
    val macIdCacheManager = remember { MacIdCacheManager(
        context,
        repository.getMacIdCacheDao(),
        GoogleSheetsAPI(context)
    ) }

    // UndoManager for undo functionality
    val undoManager = remember { UndoManager() }

    // SolutionReminderManager for tracking pending solutions
    val solutionReminderManager = remember { SolutionReminderManager() }

    // Eligibility dialog state
    var showEligibilityDialog by remember { mutableStateOf(false) }
    var eligibilityMessage by remember { mutableStateOf("") }
    var eligibilityRequiresDriverPairing by remember { mutableStateOf(false) }
    var eligibilityRequiresFrequencyTest by remember { mutableStateOf(false) }
    var eligibilityRequiresSongTest by remember { mutableStateOf(false) }
    var pendingNavigationRoute by remember { mutableStateOf<String?>(null) }

    // Load criteria from saved JSON file on startup
    LaunchedEffect(Unit) {
        Log.d("AppNav", "🔄 App starting - loading criteria from saved JSON file...")
        val loaded = com.example.fqcapp.core.CriteriaJsonStorage.loadFromFile(context)
        if (loaded != null) {
            com.example.fqcapp.core.CriteriaRepository.update(loaded)
            Log.d("AppNav", "✅ Criteria loaded on startup from JSON")
        } else {
            Log.d("AppNav", "⚠️ No saved criteria JSON file, using defaults")
        }
    }

    // Initialize services with error handling
    val sheetsService = remember {
        try {
            GoogleSheetsService(context, repository.getMacIdCacheDao())
        } catch (e: Exception) {
            e.printStackTrace()
            null
        }
    }
    val bluetoothService = remember {
        try {
            BluetoothService(context)
        } catch (e: Exception) {
            e.printStackTrace()
            null
        }
    }
    val connectionManager = remember {
        try {
            if (sheetsService != null && bluetoothService != null) {
                ConnectionManager(bluetoothService, sheetsService)
            } else null
        } catch (e: Exception) {
            e.printStackTrace()
            null
        }
    }

    // Permission handler is now passed as parameter

    // Current session state
    var currentSessionId by remember { mutableStateOf<Long?>(null) }
    var currentSerialNumber by remember { mutableStateOf<String?>(null) }
    var currentMacAddress by remember { mutableStateOf("") }
    var isReferenceSerial by remember { mutableStateOf(false) } // Track if serial is generated reference
    var dataUploadStatus by remember { mutableStateOf("Unknown") }
    var connectedDeviceName by remember { mutableStateOf<String?>(null) }

    // Device data cache manager
    val deviceDataCache = remember { com.example.fqcapp.core.DeviceDataCacheManager(context) }

    // Fetch device data from Supabase when serial number is set (with caching)
    LaunchedEffect(currentSerialNumber) {
        if (currentSerialNumber != null && currentSerialNumber!!.isNotBlank()) {
            Log.d("Navigation", "═══════════════════════════════════════════════════════════")
            Log.d("Navigation", "🔍 [NAVIGATION] SERIAL NUMBER SCANNED/SET")
            Log.d("Navigation", "   Serial Number: ${currentSerialNumber}")
            Log.d("Navigation", "   MAC Address: $currentMacAddress")
            Log.d("Navigation", "   Device Name: ${connectedDeviceName ?: "N/A"}")
            Log.d("Navigation", "───────────────────────────────────────────────────────────")

            scope.launch {
                try {
                    // Check cache first
                    val cachedData = deviceDataCache.getCachedData(currentSerialNumber!!)

                    if (cachedData != null) {
                        Log.d("Navigation", "📦 [CACHE] Using cached device data (no API call)")
                        Log.d("Navigation", "   Device Status: ${cachedData.device_status}")
                        Log.d("Navigation", "   Current Stage: ${cachedData.current_stage}")
                        Log.d("Navigation", "   Max Iterations:")
                        Log.d("Navigation", "     • Frequency: ${cachedData.max_frequency_iteration}")
                        Log.d("Navigation", "     • Song: ${cachedData.max_song_iteration}")
                        Log.d("Navigation", "     • FQC: ${cachedData.max_fqc_iteration}")
                        Log.d("Navigation", "     • Driver Pairing: ${cachedData.max_driver_pairing_iteration}")
                        Log.d("Navigation", "     • Changed Parts: ${cachedData.max_changed_parts_iteration}")
                        Log.d("Navigation", "═══════════════════════════════════════════════════════════")
                        return@launch
                    }

                    // Cache miss or expired - fetch from Supabase
                    Log.d("Navigation", "📋 [ACTION] Fetching device data from Supabase (cache miss/expired)...")
                    val deviceDataService = com.example.fqcapp.supabase.SupabaseDeviceDataService()
                    val snapshot = deviceDataService.fetchDeviceData(currentSerialNumber!!)

                    if (snapshot != null) {
                        // Cache the fetched data
                        deviceDataCache.setCachedData(currentSerialNumber!!, snapshot)

                        Log.d("Navigation", "───────────────────────────────────────────────────────────")
                        Log.d("Navigation", "✅ [NAVIGATION] Device data fetched from Supabase")
                        Log.d("Navigation", "   Device Status: ${snapshot.device_status}")
                        Log.d("Navigation", "   Current Stage: ${snapshot.current_stage}")
                        Log.d("Navigation", "   Max Iterations:")
                        Log.d("Navigation", "     • Frequency: ${snapshot.max_frequency_iteration}")
                        Log.d("Navigation", "     • Song: ${snapshot.max_song_iteration}")
                        Log.d("Navigation", "     • FQC: ${snapshot.max_fqc_iteration}")
                        Log.d("Navigation", "     • Driver Pairing: ${snapshot.max_driver_pairing_iteration}")
                        Log.d("Navigation", "     • Changed Parts: ${snapshot.max_changed_parts_iteration}")
                        Log.d("Navigation", "   Last Update: ${snapshot.last_update_timestamp}")
                        Log.d("Navigation", "═══════════════════════════════════════════════════════════")
                    } else {
                        Log.w("Navigation", "───────────────────────────────────────────────────────────")
                        Log.w("Navigation", "⚠️ [NAVIGATION] No device data found in Supabase (new device)")
                        Log.w("Navigation", "   Serial Number: ${currentSerialNumber}")
                        Log.w("Navigation", "   This is a new device - no previous test data")
                        Log.w("Navigation", "═══════════════════════════════════════════════════════════")
                    }
                } catch (e: Exception) {
                    Log.e("Navigation", "═══════════════════════════════════════════════════════════")
                    Log.e("Navigation", "❌ [NAVIGATION] Error fetching device data from Supabase")
                    Log.e("Navigation", "   Serial Number: ${currentSerialNumber}")
                    Log.e("Navigation", "   Error: ${e.message}")
                    Log.e("Navigation", "   Stack trace: ${e.stackTraceToString()}")
                    Log.e("Navigation", "═══════════════════════════════════════════════════════════")
                }
            }
        }
    }

    // Callback function to update device info (for PCB change)
    val updateDeviceInfoCallback: (String, String) -> Unit = { newSerialNumber, newMacId ->
        currentMacAddress = newMacId
        currentSerialNumber = newSerialNumber
        android.util.Log.d("Navigation", "✅ [PCB_UPDATE] Updated MAC ID to: $newMacId, Serial to: $newSerialNumber")
    }

    // Track current route to only run periodic checks on landing page
    val navBackStackEntry by nav.currentBackStackEntryAsState()
    val currentRoute = navBackStackEntry?.destination?.route ?: Routes.LANDING

    // Periodic Bluetooth device detection - ONLY on landing page
    LaunchedEffect(bluetoothService, currentRoute) {
        // Only start periodic checks if we're on the landing page
        if (bluetoothService != null && currentRoute == Routes.LANDING) {
            android.util.Log.d("Navigation", "🟢 Starting periodic Bluetooth check (on landing page: $currentRoute)")
            while (true) {
                try {
                    // Check current route at the start of each iteration
                    val currentNavBackStackEntry = nav.currentBackStackEntry
                    val actualRoute = currentNavBackStackEntry?.destination?.route ?: Routes.LANDING

                    // If we're no longer on landing page, stop immediately
                    if (actualRoute != Routes.LANDING) {
                        android.util.Log.d("Navigation", "🔴 Stopping periodic Bluetooth check (navigated away from landing page: $actualRoute)")
                        break
                    }

                    // Check for connected device every 10 seconds
                    val connectedDevice = bluetoothService.probeCurrentlyConnected()
                    if (connectedDevice != null) {
                        android.util.Log.d("Navigation", "Periodic check: Found connected device: ${connectedDevice.name} - ${connectedDevice.macAddress}")

                        // IMPORTANT: If MAC ID changed, clear previous serial number
                        if (currentMacAddress.isNotBlank() && currentMacAddress != connectedDevice.macAddress) {
                            android.util.Log.d("Navigation", "🔄 MAC ID changed from $currentMacAddress to ${connectedDevice.macAddress} - clearing previous serial")
                            currentSerialNumber = null
                            isReferenceSerial = false
                        }

                        connectedDeviceName = connectedDevice.name
                        currentMacAddress = connectedDevice.macAddress

                        // If we don't have a serial number, try to look it up from MAC ID (reverse lookup)
                        // This handles the case where device is connected manually without scanning QR code
                        if (currentSerialNumber == null && connectedDevice.macAddress.isNotBlank()) {
                            android.util.Log.d("Navigation", "🔍 Performing reverse lookup: MAC ID -> Serial Number")
                            android.util.Log.d("Navigation", "   MAC ID: ${connectedDevice.macAddress}")
                            try {
                                val serialFromMac = macIdCacheManager.getSerialNumberByMacId(connectedDevice.macAddress)
                                if (serialFromMac != null && serialFromMac.isNotBlank()) {
                                    android.util.Log.d("Navigation", "✅ Found serial number from MAC ID: $serialFromMac")
                                    // Directly set the serial number and MAC address
                                    // The device is already connected, so we just need to update our state
                                    currentSerialNumber = serialFromMac
                                    isReferenceSerial = false
                                    android.util.Log.d("Navigation", "✅ Updated device info - Serial: $serialFromMac, MAC: ${connectedDevice.macAddress}")
                                } else {
                                    // MAC ID not found - generate reference serial number
                                    val referenceSerial = SerialGenerator.generateSystemSerial(connectedDevice.macAddress)
                                    android.util.Log.w("Navigation", "⚠️ Serial number not found for MAC ID: ${connectedDevice.macAddress}")
                                    android.util.Log.w("Navigation", "   Generating reference serial: $referenceSerial")
                                    currentSerialNumber = referenceSerial
                                    isReferenceSerial = true
                                    android.util.Log.d("Navigation", "✅ Using reference serial: $referenceSerial for MAC: ${connectedDevice.macAddress}")
                                }
                            } catch (e: Exception) {
                                android.util.Log.e("Navigation", "❌ Error during MAC ID reverse lookup", e)
                                // On error, still generate reference serial
                                val referenceSerial = SerialGenerator.generateSystemSerial(connectedDevice.macAddress)
                                currentSerialNumber = referenceSerial
                                isReferenceSerial = true
                                android.util.Log.d("Navigation", "✅ Generated reference serial on error: $referenceSerial")
                            }
                        }
                    } else {
                        android.util.Log.d("Navigation", "Periodic check: No connected device found")
                        // Don't clear the current device info immediately - wait for user to scan new QR
                    }
                } catch (e: Exception) {
                    android.util.Log.e("Navigation", "Error in periodic Bluetooth check", e)
                }

                // Wait 10 seconds before next check
                kotlinx.coroutines.delay(10000)
            }
            android.util.Log.d("Navigation", "🛑 Periodic Bluetooth check loop ended")
        } else {
            if (bluetoothService != null && currentRoute != Routes.LANDING) {
                android.util.Log.d("Navigation", "⏸️ Periodic Bluetooth check not started (not on landing page: $currentRoute)")
            } else if (bluetoothService == null) {
                android.util.Log.d("Navigation", "⏸️ Periodic Bluetooth check not started (bluetoothService is null)")
            }
        }
    }

    // Connection flow state
    var showConnectionProgress by remember { mutableStateOf(false) }
    var connectionStep by remember { mutableStateOf(ConnectionStep.SEARCHING_SHEET) }
    var connectionData by remember { mutableStateOf<String?>(null) } // MAC ID or device name
    var showConnectionError by remember { mutableStateOf(false) }
    var errorMessage by remember { mutableStateOf("") }
    var showDeviceSelection by remember { mutableStateOf(false) }
    var nearbyDevices by remember { mutableStateOf<List<BluetoothService.DeviceInfo>>(emptyList()) }
    var pendingSerialNumber by remember { mutableStateOf<String?>(null) }

    // Permission state
    var showPermissionRequest by remember { mutableStateOf(false) }
    var missingPermissions by remember { mutableStateOf<List<String>>(emptyList()) }

    // Drawer state
    val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)
    var serialNumberPrefix by remember { mutableStateOf(prefsManager.getSerialNumberPrefix()) }
    var showPrefixDialog by remember { mutableStateOf(false) }
    var showUnpairConfirmDialog by remember { mutableStateOf(false) }
    var showUnpairResultDialog by remember { mutableStateOf(false) }
    var unpairResult by remember { mutableStateOf("") }

    // Long press speed setting
    var longPressSpeed by remember { mutableStateOf(prefsManager.getLongPressSpeed()) }
    var showLongPressSpeedDialog by remember { mutableStateOf(false) }

    // Simulate data upload status updates
    LaunchedEffect(currentSerialNumber) {
        if (currentSerialNumber != null) {
            dataUploadStatus = "Pending"
            // Simulate upload process
            kotlinx.coroutines.delay(3000) // 3 second delay
            dataUploadStatus = "Synced"
            android.util.Log.d("Navigation", "Data upload simulation completed for: $currentSerialNumber")
        }
    }

    // Auto-refresh MAC ID cache on startup if older than 1 hour
    LaunchedEffect(Unit) {
        try {
            if (macIdCacheManager.shouldRefreshCache()) {
                android.util.Log.d("Navigation", "MAC ID cache is stale, refreshing...")
                val success = macIdCacheManager.refreshCache()
                if (success) {
                    android.util.Log.d("Navigation", "✅ MAC ID cache refreshed successfully")
                } else {
                    android.util.Log.w("Navigation", "⚠️ Failed to refresh MAC ID cache")
                }
            } else {
                android.util.Log.d("Navigation", "MAC ID cache is up-to-date")
            }
        } catch (e: Exception) {
            android.util.Log.e("Navigation", "Error checking/refreshing MAC ID cache", e)
        }
    }

    // Background sync for unsynced driver pairing entries
    LaunchedEffect(Unit) {
        try {
            val driverPairingService = DriverPairingSheetsService(context)
            val driverPairingCacheManager = DriverPairingCacheManager(
                repository.getDriverPairingCacheDao(),
                driverPairingService
            )

            // Check for unsynced entries and sync in background
            if (driverPairingCacheManager.hasUnsyncedEntries()) {
                android.util.Log.d("Navigation", "Found unsynced driver pairing entries, syncing...")
                scope.launch {
                    val syncedCount = driverPairingCacheManager.syncUnsyncedEntries()
                    android.util.Log.d("Navigation", "✅ Synced $syncedCount driver pairing entries to Google Sheets")
                }
            }
        } catch (e: Exception) {
            android.util.Log.e("Navigation", "Error syncing driver pairing entries", e)
        }
    }



    // Simple direct connection function - bypasses ConnectionManager complexity
    fun simpleConnect(serialNumber: String, macIdOverride: String? = null) {
        android.util.Log.d("Navigation", "Simple connect for serial: $serialNumber${if (macIdOverride != null) " with MAC override: $macIdOverride" else ""}")

        if (sheetsService == null || bluetoothService == null) {
            android.util.Log.w("Navigation", "Services not initialized")
            errorMessage = "Services not initialized"
            showConnectionError = true
            return
        }

        showConnectionProgress = true
        connectionStep = ConnectionStep.SEARCHING_SHEET
        connectionData = null

        scope.launch {
            try {
                val macId: String?

                if (macIdOverride != null && macIdOverride.isNotBlank()) {
                    // Use the provided MAC ID (from PCB change)
                    android.util.Log.d("Navigation", "Step 1: Using provided MAC ID (PCB change): $macIdOverride")
                    macId = macIdOverride
                    connectionStep = ConnectionStep.MAC_FOUND
                    connectionData = macId
                    currentMacAddress = macId
                } else {
                    // Step 1: Search Google Sheets for MAC ID
                    android.util.Log.d("Navigation", "Step 1: Searching Google Sheets for serial: $serialNumber")
                    connectionStep = ConnectionStep.SEARCHING_SHEET
                    connectionData = null

                    macId = sheetsService.getMacIdBySerialNumber(serialNumber)

                    if (macId == null) {
                        android.util.Log.e("Navigation", "MAC ID not found for serial: $serialNumber")
                        errorMessage = "Serial number '$serialNumber' not found in database"
                        showConnectionProgress = false
                        showConnectionError = true
                        return@launch
                    }

                    // Step 2: MAC ID Found - Display it
                    android.util.Log.d("Navigation", "Step 2: MAC ID found: $macId")
                    connectionStep = ConnectionStep.MAC_FOUND
                    connectionData = macId
                    currentMacAddress = macId
                }

                kotlinx.coroutines.delay(1000) // Show MAC ID for 1 second

                // Step 3: Search for Bluetooth device
                android.util.Log.d("Navigation", "Step 3: Searching for Bluetooth device with MAC: $macId")
                connectionStep = ConnectionStep.SEARCHING_DEVICE
                connectionData = macId

                val device = bluetoothService.findDeviceByMacId(macId)

                if (device == null) {
                    android.util.Log.e("Navigation", "Bluetooth device not found for MAC: $macId")
                    errorMessage = "Device not found with MAC address: $macId"
                    showConnectionProgress = false
                    showConnectionError = true
                    return@launch
                }

                // Step 4: Connect to device
                android.util.Log.d("Navigation", "Step 4: Connecting to device: ${device.name}")
                connectionStep = ConnectionStep.CONNECTING
                connectionData = device.name

                val connected = bluetoothService.connectToDevice(device)

                if (!connected) {
                    android.util.Log.e("Navigation", "Failed to connect to device: ${device.name}")
                    errorMessage = "Failed to connect to device: ${device.name}"
                    showConnectionProgress = false
                    showConnectionError = true
                    return@launch
                }

                // Success!
                android.util.Log.d("Navigation", "Connection successful!")
                connectionStep = ConnectionStep.SUCCESS
                kotlinx.coroutines.delay(500) // Show success message briefly
                showConnectionProgress = false

                // Create session and navigate to landing
                try {
                    // Ensure Device and Operator records exist
                    val existingDevice = repository.getDeviceBySerialNumber(serialNumber)
                    if (existingDevice == null) {
                        val today = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
                            .format(java.util.Date())
                        // NOTE: macId is deprecated - MAC comes from active PCB link
                        // Setting to empty string - MAC will be derived from PCB link when needed
                        repository.insertDevice(Device(
                            serialNumber = serialNumber,
                            macId = "",  // Deprecated - MAC comes from active PCB link
                            color = "",
                            createdDate = today,
                            finalStatus = "IN_PROGRESS",
                            totalIterations = 0,
                            totalTimeHours = 0.0,
                            finalOperator = "",
                            firstTestDate = today,
                            finalShipDate = "",
                            needsSync = true,
                            lastSyncTimestamp = 0
                        ))
                    }

                    val operatorId = prefsManager.getOperatorId()
                    val existingOperator = repository.getOperatorById(operatorId)
                    if (existingOperator == null) {
                        repository.insertOperator(Operator(
                            id = operatorId,
                            name = operatorName
                        ))
                    }

                    val sessionId = repository.insertSession(
                        FQCSession(
                            operatorId = operatorId,
                            serialNumber = serialNumber,
                            status = "active"
                        )
                    )
                    currentSessionId = sessionId
                    currentSerialNumber = serialNumber
                    isReferenceSerial = false // Reset flag when real serial is scanned
                    dataUploadStatus = "Pending"
                    android.util.Log.d("Navigation", "Session created: $sessionId")
                } catch (e: Exception) {
                    android.util.Log.e("Navigation", "Error creating session", e)
                }

            } catch (e: Exception) {
                android.util.Log.e("Navigation", "Exception in simple connect", e)
                errorMessage = "Connection error: ${e.message ?: "Unknown error"}"
                showConnectionProgress = false
                showConnectionError = true
            }
        }
    }

    ModalNavigationDrawer(
        drawerState = drawerState,
        drawerContent = {
            AppDrawer(
                operatorName = operatorName,
                serialNumberPrefix = serialNumberPrefix,
                onSerialPrefixClick = {
                    scope.launch {
                        drawerState.close()
                        showPrefixDialog = true
                    }
                },
                onForgetDevicesClick = {
                    scope.launch {
                        drawerState.close()
                        showUnpairConfirmDialog = true
                    }
                },
                onLongPressSpeedClick = {
                    scope.launch {
                        drawerState.close()
                        showLongPressSpeedDialog = true
                    }
                },
                onSyncConfigClick = {
                    scope.launch {
                        drawerState.close()
                        android.widget.Toast.makeText(context, "Syncing config from Google Sheets...", android.widget.Toast.LENGTH_SHORT).show()
                        try {
                            // Sync criteria
                            val criteriaResult = com.example.fqcapp.core.CriteriaSync.syncFromGoogleSheets(
                                context = context,
                                sheetId = "1pz_4jusyFCFZkg5Rkw5M3lkBmFlik14iu9tmtJezpD0",
                                sheetName = "Test_parameters"
                            )

                            // Sync operator credentials
                            val operatorResult = com.example.fqcapp.core.OperatorCredentialSync.syncFromGoogleSheets(
                                context = context,
                                sheetId = "1pz_4jusyFCFZkg5Rkw5M3lkBmFlik14iu9tmtJezpD0",
                                sheetName = "Operator_Credentials"
                            )

                            val criteriaSuccess = criteriaResult.isSuccess
                            val operatorSuccess = operatorResult.isSuccess

                            if (criteriaSuccess && operatorSuccess) {
                                val operatorCount = operatorResult.getOrNull() ?: 0
                                android.widget.Toast.makeText(context, "✅ Config synced! ($operatorCount operators)", android.widget.Toast.LENGTH_SHORT).show()
                                Log.d("Navigation", "✅ Sync completed successfully - Criteria and $operatorCount operators")
                            } else {
                                val errors = mutableListOf<String>()
                                val errorDetails = mutableListOf<String>()
                                if (!criteriaSuccess) {
                                    errors.add("Criteria")
                                    val criteriaError = criteriaResult.exceptionOrNull()?.message ?: "Unknown error"
                                    errorDetails.add("Criteria: $criteriaError")
                                }
                                if (!operatorSuccess) {
                                    errors.add("Operators")
                                    val operatorError = operatorResult.exceptionOrNull()?.message ?: "Unknown error"
                                    errorDetails.add("Operators: $operatorError")
                                    Log.e("Navigation", "❌ Operator sync error details: $operatorError")
                                }
                                val errorMsg = errors.joinToString(", ")
                                val errorDetailMsg = errorDetails.joinToString("\n")
                                android.widget.Toast.makeText(context, "⚠️ Partial sync: $errorMsg failed\n$errorDetailMsg", android.widget.Toast.LENGTH_LONG).show()
                                Log.e("Navigation", "❌ Partial sync failed: $errorMsg")
                                Log.e("Navigation", "❌ Error details: $errorDetailMsg")
                            }
                        } catch (e: Exception) {
                            android.util.Log.e("Navigation", "❌ Error syncing config", e)
                            android.widget.Toast.makeText(context, "Config sync error: ${e.message}", android.widget.Toast.LENGTH_LONG).show()
                        }
                    }
                },
                onSyncDataClick = {
                    scope.launch {
                        drawerState.close()
                        dataUploadStatus = "Syncing..."
                        android.widget.Toast.makeText(context, "Starting hybrid data sync...", android.widget.Toast.LENGTH_SHORT).show()

                        try {
                            // Use SQL-based sync service with current serial number and operator name
                            val operatorName = prefsManager.getOperatorName() ?: "Unknown"
                            val syncService = com.example.fqcapp.services.SQLDataSyncService(context, repository)
                            val success = syncService.syncDeviceData(scannedSerialNumber = currentSerialNumber, operatorName = operatorName)

                            if (success) {
                                dataUploadStatus = "Synced"
                                android.widget.Toast.makeText(context, "✅ Data sync completed successfully!", android.widget.Toast.LENGTH_LONG).show()
                            } else {
                                dataUploadStatus = "Failed"
                                android.widget.Toast.makeText(context, "❌ Data sync failed. Check logs for details.", android.widget.Toast.LENGTH_LONG).show()
                            }

                        } catch (e: Exception) {
                            android.util.Log.e("Navigation", "Manual sync failed", e)
                            dataUploadStatus = "Failed"
                            android.widget.Toast.makeText(context, "Sync failed: ${e.message}", android.widget.Toast.LENGTH_LONG).show()
                        }
                    }
                },
                onSyncDriverPairClick = {
                    scope.launch {
                        drawerState.close()
                        android.util.Log.d("Navigation", "🔵 [SYNC_DRIVER_PAIR] Manual sync Driver Pair button tapped")
                        android.widget.Toast.makeText(context, "Syncing driver pairing data...", android.widget.Toast.LENGTH_SHORT).show()

                        try {
                            android.util.Log.d("Navigation", "🔵 [SYNC_DRIVER_PAIR] Initializing services...")
                            val driverPairingService = DriverPairingSheetsService(context)
                            val driverPairingCacheManager = DriverPairingCacheManager(
                                repository.getDriverPairingCacheDao(),
                                driverPairingService
                            )

                            android.util.Log.d("Navigation", "🔵 [SYNC_DRIVER_PAIR] Checking for unsynced entries...")
                            val hasUnsynced = driverPairingCacheManager.hasUnsyncedEntries()

                            if (hasUnsynced) {
                                android.util.Log.d("Navigation", "🔵 [SYNC_DRIVER_PAIR] Found unsynced entries, starting sync...")
                                val syncedCount = driverPairingCacheManager.syncUnsyncedEntries()
                                android.util.Log.d("Navigation", "✅ [SYNC_DRIVER_PAIR] Sync completed: $syncedCount entries synced")

                                if (syncedCount > 0) {
                                    android.widget.Toast.makeText(context, "✅ Synced $syncedCount driver pairing entries!", android.widget.Toast.LENGTH_SHORT).show()
                                } else {
                                    android.widget.Toast.makeText(context, "⚠️ No entries synced. Check logs for details.", android.widget.Toast.LENGTH_LONG).show()
                                }
                            } else {
                                android.util.Log.d("Navigation", "✅ [SYNC_DRIVER_PAIR] No unsynced entries found")
                                android.widget.Toast.makeText(context, "✅ All driver pairing data is already synced!", android.widget.Toast.LENGTH_SHORT).show()
                            }
                        } catch (e: Exception) {
                            android.util.Log.e("Navigation", "❌ [SYNC_DRIVER_PAIR] Error during sync", e)
                            android.widget.Toast.makeText(context, "❌ Sync failed: ${e.message}", android.widget.Toast.LENGTH_LONG).show()
                        }
                    }
                },
                onTestUploadClick = {
                    scope.launch {
                        drawerState.close()
                        android.widget.Toast.makeText(context, "Generating test data...", android.widget.Toast.LENGTH_SHORT).show()

                        try {
                            // Generate test data
                            val testDataGenerator = com.example.fqcapp.utils.TestDataGenerator(context)
                            val success = testDataGenerator.generateTestData()

                            if (success) {
                                android.widget.Toast.makeText(context, "Test data generated! Now testing upload...", android.widget.Toast.LENGTH_SHORT).show()

                                // Test SQL sync
                                val operatorName = prefsManager.getOperatorName() ?: "TestOperator"
                                val syncService = com.example.fqcapp.services.SQLDataSyncService(context, repository)
                                val success = syncService.syncDeviceData(scannedSerialNumber = currentSerialNumber, operatorName = operatorName)

                                if (success) {
                                    dataUploadStatus = "Synced"
                                    android.widget.Toast.makeText(context, "✅ Test upload completed successfully!", android.widget.Toast.LENGTH_LONG).show()
                                } else {
                                    dataUploadStatus = "Failed"
                                    android.widget.Toast.makeText(context, "❌ Test upload failed", android.widget.Toast.LENGTH_LONG).show()
                                }

                                // Show test data summary
                                val summary = testDataGenerator.getTestDataSummary()
                                android.util.Log.d("Navigation", "Test data summary:\n$summary")

                            } else {
                                android.widget.Toast.makeText(context, "Failed to generate test data", android.widget.Toast.LENGTH_LONG).show()
                            }
                        } catch (e: Exception) {
                            android.util.Log.e("Navigation", "Error in test upload", e)
                            android.widget.Toast.makeText(context, "Test upload failed: ${e.message}", android.widget.Toast.LENGTH_LONG).show()
                        }
                    }
                },
                onTestGoogleSheetsClick = {
                    scope.launch {
                        drawerState.close()
                        android.widget.Toast.makeText(context, "Testing Google Sheets connection...", android.widget.Toast.LENGTH_SHORT).show()

                        try {
                            if (sheetsService != null) {
                                // Test general connection
                                val success = sheetsService.testGoogleSheetsConnection()

                                // Test specific serial number
                                val testSerial = "SLC251EG000641"
                                val macId = sheetsService.testSpecificSerial(testSerial)

                                if (success && macId != null) {
                                    android.widget.Toast.makeText(context, "✅ Google Sheets working! MAC for $testSerial: $macId", android.widget.Toast.LENGTH_LONG).show()
                                } else if (success) {
                                    android.widget.Toast.makeText(context, "✅ Google Sheets connected but $testSerial not found", android.widget.Toast.LENGTH_LONG).show()
                                } else {
                                    android.widget.Toast.makeText(context, "❌ Google Sheets connection failed. Using mock data.", android.widget.Toast.LENGTH_LONG).show()
                                }
                            } else {
                                android.widget.Toast.makeText(context, "❌ Google Sheets service not available", android.widget.Toast.LENGTH_LONG).show()
                            }
                        } catch (e: Exception) {
                            android.util.Log.e("Navigation", "Error testing Google Sheets", e)
                            android.widget.Toast.makeText(context, "❌ Error testing Google Sheets: ${e.message}", android.widget.Toast.LENGTH_LONG).show()
                        }
                    }
                },
                onViewCSVClick = {
                    scope.launch {
                        drawerState.close()
                        android.widget.Toast.makeText(context, "Checking CSV data...", android.widget.Toast.LENGTH_SHORT).show()

                        try {
                            // Simple CSV viewer - just show a message
                            android.widget.Toast.makeText(context, "CSV viewer feature coming soon!", android.widget.Toast.LENGTH_LONG).show()

                        } catch (e: Exception) {
                            android.util.Log.e("Navigation", "Error viewing CSV data", e)
                            android.widget.Toast.makeText(context, "Error viewing CSV: ${e.message}", android.widget.Toast.LENGTH_LONG).show()
                        }
                    }
                },
                onViewDatabaseClick = {
                    scope.launch {
                        drawerState.close()
                        nav.navigate(Routes.DATABASE_VIEWER)
                    }
                },
                onClose = {
                    scope.launch { drawerState.close() }
                }
            )
        }
    ) {
        Scaffold { padding ->
            AppNavGraph(
                nav = nav,
                operatorName = operatorName,
                currentSerialNumber = currentSerialNumber,
                currentMacAddress = currentMacAddress,
                connectedDeviceName = connectedDeviceName,
                serialNumberPrefix = serialNumberPrefix,
                longPressSpeed = 10, // Default speed
                onLogout = onLogout,
                onOpenDrawer = {
                    scope.launch { drawerState.open() }
                },
                onSerialNumberScanned = { serialNumber, macIdOverride ->
                    // Check if this is a reference serial (starts with "TMP-")
                    isReferenceSerial = serialNumber.startsWith("TMP-")
                    pendingSerialNumber = serialNumber
                    if (permissionHandler != null && !permissionHandler.hasAllBluetoothPermissions()) {
                        permissionHandler.requestBluetoothPermissions { granted ->
                            if (granted) {
                                simpleConnect(serialNumber, macIdOverride)
                            } else {
                                missingPermissions = permissionHandler.getMissingBluetoothPermissions()
                                showPermissionRequest = true
                            }
                        }
                    } else {
                        simpleConnect(serialNumber, macIdOverride)
                    }
                },
                currentSessionId = currentSessionId,
                repository = repository,
                paddingValues = padding,
                activity = activity,
                permissionHandler = permissionHandler,
                bluetoothService = bluetoothService,
                onMacDetected = { mac -> currentMacAddress = mac },
                dataUploadStatus = dataUploadStatus,
                macIdCacheManager = macIdCacheManager,
                onForgetCurrentDevice = {
                    scope.launch {
                        // Clear current device info
                        currentSerialNumber = null
                        currentMacAddress = ""
                        currentSessionId = null
                        dataUploadStatus = "Unknown"

                        // Unpair the device if Bluetooth service is available
                        bluetoothService?.let { service ->
                            try {
                                val connectedDevice = service.getCurrentlyConnectedDevice()
                                if (connectedDevice != null) {
                                    val success = service.unpairDevice(connectedDevice.macAddress)
                                    android.util.Log.d("Navigation", "Device unpair result: $success")
                                } else {
                                    android.util.Log.d("Navigation", "No connected device to unpair")
                                }
                            } catch (e: Exception) {
                                android.util.Log.e("Navigation", "Error unpairing device", e)
                            }
                        }

                        android.widget.Toast.makeText(context, "Current device forgotten", android.widget.Toast.LENGTH_SHORT).show()
                    }
                },
                undoManager = undoManager,
                solutionReminderManager = solutionReminderManager
            )
        }

        // Connection Progress Dialog
        if (showConnectionProgress) {
            ConnectionProgressDialog(
                currentStep = connectionStep,
                additionalData = connectionData,
                onRescan = {
                    // Cancel connection and go back to scanner
                    showConnectionProgress = false
                    connectionStep = ConnectionStep.SEARCHING_SHEET
                    connectionData = null
                    nav.navigate(Routes.SCANNER) {
                        popUpTo(Routes.LANDING) { inclusive = false }
                    }
                },
                onBack = {
                    // Cancel connection and go back to landing page
                    showConnectionProgress = false
                    connectionStep = ConnectionStep.SEARCHING_SHEET
                    connectionData = null
                    nav.navigate(Routes.LANDING) {
                        popUpTo(Routes.LANDING) { inclusive = true }
                    }
                }
            )
        }

        // Connection Error Dialog
        if (showConnectionError) {
            ConnectionErrorDialog(
                errorMessage = errorMessage,
                onRetry = {
                    showConnectionError = false
                    pendingSerialNumber?.let { serial ->
                        if (connectionManager == null) {
                            // Services failed, continue anyway
                            scope.launch {
                                val operatorId = prefsManager.getOperatorId()
                                val sessionId = repository.insertSession(
                                    FQCSession(
                                        operatorId = operatorId,
                                        serialNumber = serial,
                                        status = "active"
                                    )
                                )
                                currentSessionId = sessionId
                                currentSerialNumber = serial
                            }
                            return@let
                        }
                        showConnectionProgress = true
                        connectionStep = ConnectionStep.SEARCHING_SHEET
                        connectionData = null
                        scope.launch {
                            // Use the original working method
                            connectionManager.connectToDeviceBySerial(
                                serialNumber = serial,
                                onStepChange = { step, data ->
                                    connectionStep = step
                                    connectionData = data
                                },
                                onError = { error ->
                                    errorMessage = error
                                    showConnectionProgress = false
                                    showConnectionError = true
                                },
                                onSuccess = {
                                    showConnectionProgress = false
                                    scope.launch {
                                        val operatorId = prefsManager.getOperatorId()
                                        val sessionId = repository.insertSession(
                                            FQCSession(
                                                operatorId = operatorId,
                                                serialNumber = serial,
                                                status = "active"
                                            )
                                        )
                                        currentSessionId = sessionId
                                        currentSerialNumber = serial
                                    }
                                }
                            )
                        }
                    }
                },
                onContinueAnyway = {
                    showConnectionError = false
                    // Continue without Bluetooth connection
                    pendingSerialNumber?.let { serial ->
                        scope.launch {
                            try {
                                val operatorId = prefsManager.getOperatorId()

                                // Ensure Device record exists
                                // NOTE: macId is deprecated - MAC comes from active PCB link
                                // Setting to empty string - MAC will be derived from PCB link when needed
                                repository.insertDevice(
                                    Device(
                                        serialNumber = serial,
                                        macId = "",  // Deprecated - MAC comes from active PCB link
                                        color = "Unknown",
                                        createdDate = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date()),
                                        finalStatus = "IN_PROGRESS"
                                    )
                                )

                                // Ensure Operator record exists
                                val operator = repository.getOperatorById(operatorId)
                                if (operator == null) {
                                    repository.insertOperator(
                                        Operator(
                                            id = operatorId,
                                            name = operatorName
                                        )
                                    )
                                }

                                val sessionId = repository.insertSession(
                                    FQCSession(
                                        operatorId = operatorId,
                                        serialNumber = serial,
                                        status = "active"
                                    )
                                )
                                currentSessionId = sessionId
                                currentSerialNumber = serial
                                android.util.Log.d("Navigation", "Session created successfully: $sessionId")
                            } catch (e: Exception) {
                                android.util.Log.e("Navigation", "Error creating session", e)
                            }
                        }
                    }
                },
                onDismiss = { 
                    showConnectionError = false
                    // Also show device selection option if error was device-related
                    if (errorMessage.contains("not found nearby", ignoreCase = true) && bluetoothService != null) {
                        scope.launch {
                            showDeviceSelection = true
                            nearbyDevices = bluetoothService.getNearbyDevices(15)
                        }
                    }
                }
            )
        }

        // Device Selection Dialog
        if (showDeviceSelection) {
            DeviceSelectionDialog(
                devices = nearbyDevices,
                onDeviceSelected = { macAddress ->
                    showDeviceSelection = false
                    if (connectionManager == null) {
                        // Services failed, skip connection
                        return@DeviceSelectionDialog
                    }
                    showConnectionProgress = true
                    connectionStep = ConnectionStep.SEARCHING_DEVICE
                    scope.launch {
                        connectionManager.connectToDeviceByMac(
                            macAddress = macAddress,
                            onStepChange = { step, data ->
                                connectionStep = step
                                connectionData = data
                            },
                            onError = { error ->
                                errorMessage = error
                                showConnectionProgress = false
                                showConnectionError = true
                            },
                            onSuccess = {
                                showConnectionProgress = false
                                pendingSerialNumber?.let { serial ->
                                    scope.launch {
                                        try {
                                            val operatorId = prefsManager.getOperatorId()

                                            // Ensure Device record exists
                                            repository.insertDevice(
                                                Device(
                                                    serialNumber = serial,
                                                    macId = currentMacAddress.ifBlank { "Unknown" },
                                                    color = "Unknown",
                                                    createdDate = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date()),
                                                    finalStatus = "IN_PROGRESS"
                                                )
                                            )

                                            // Ensure Operator record exists
                                            val operator = repository.getOperatorById(operatorId)
                                            if (operator == null) {
                                                repository.insertOperator(
                                                    Operator(
                                                        id = operatorId,
                                                        name = operatorName
                                                    )
                                                )
                                            }

                                            val sessionId = repository.insertSession(
                                                FQCSession(
                                                    operatorId = operatorId,
                                                    serialNumber = serial,
                                                    status = "active"
                                                )
                                            )
                                            currentSessionId = sessionId
                                            currentSerialNumber = serial
                                            android.util.Log.d("Navigation", "Session created successfully: $sessionId")
                                        } catch (e: Exception) {
                                            android.util.Log.e("Navigation", "Error creating session", e)
                                        }
                                    }
                                }
                            }
                        )
                    }
                },
                onDismiss = { showDeviceSelection = false }
            )
        }

        // Permission Request Dialog
        if (showPermissionRequest && permissionHandler != null) {
            PermissionRequestDialog(
                missingPermissions = missingPermissions,
                permissionExplanation = permissionHandler.getPermissionExplanation(missingPermissions),
                onRequestPermissions = {
                    permissionHandler.requestBluetoothPermissions { granted ->
                        if (granted) {
                            showPermissionRequest = false
                            pendingSerialNumber?.let { serial ->
                                simpleConnect(serial)
                            }
                        } else {
                            // Permissions denied - show error
                            showPermissionRequest = false
                            errorMessage = "Bluetooth permissions are required for automatic device connection.\n\nPlease grant Location permission from App Settings to enable this feature.\n\nYou can still use the app by selecting \"Continue Anyway\" when scanning."
                            showConnectionError = true
                        }
                    }
                },
                onOpenSettings = {
                    showPermissionRequest = false
                    permissionHandler.openAppSettings()
                },
                onDismiss = {
                    showPermissionRequest = false
                    // Show error suggesting to continue without Bluetooth
                    errorMessage = "Bluetooth permissions not granted.\n\nYou can use \"Continue Anyway\" to skip automatic Bluetooth connection."
                    showConnectionError = true
                }
            )
        }

        // Serial Prefix Setup Dialog
        if (showPrefixDialog) {
            SerialPrefixSetupDialog(
                currentPrefix = serialNumberPrefix,
                onDismiss = { showPrefixDialog = false },
                onSave = { prefix ->
                    prefsManager.saveSerialNumberPrefix(prefix)
                    serialNumberPrefix = prefix
                }
            )
        }

        // Unpair Confirmation Dialog
        if (showUnpairConfirmDialog) {
            androidx.compose.material3.AlertDialog(
                onDismissRequest = { showUnpairConfirmDialog = false },
                icon = {
                    androidx.compose.material3.Text("⚠️", style = androidx.compose.material3.MaterialTheme.typography.headlineLarge)
                },
                title = { 
                    androidx.compose.material3.Text(
                        "Forget All Devices?",
                        fontWeight = androidx.compose.ui.text.font.FontWeight.Bold
                    ) 
                },
                text = { 
                    Column {
                        androidx.compose.material3.Text(
                            "This will remove ALL paired Bluetooth devices from your phone's memory.",
                            style = androidx.compose.material3.MaterialTheme.typography.bodyMedium
                        )
                        Spacer(modifier = Modifier.height(12.dp))
                        androidx.compose.material3.Text(
                            "Benefits:",
                            fontWeight = androidx.compose.ui.text.font.FontWeight.Bold,
                            style = androidx.compose.material3.MaterialTheme.typography.bodyMedium
                        )
                        androidx.compose.material3.Text(
                            "• Clears device storage limit\n• Fixes connection issues\n• Fresh start for new pairings",
                            style = androidx.compose.material3.MaterialTheme.typography.bodySmall
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        androidx.compose.material3.Text(
                            "Are you sure?",
                            fontWeight = androidx.compose.ui.text.font.FontWeight.Bold,
                            color = androidx.compose.ui.graphics.Color(0xFFFF5722)
                        )
                    }
                },
                confirmButton = {
                    androidx.compose.material3.Button(
                        onClick = {
                            showUnpairConfirmDialog = false
                            bluetoothService?.let { service ->
                                val count = service.unpairAllDevices()
                                unpairResult = if (count > 0) {
                                    "✅ Successfully removed $count device(s) from memory!\n\nYour device storage is now clear and ready for new connections."
                                } else {
                                    "ℹ️ No paired devices found.\n\nYour device memory is already clear!"
                                }
                                showUnpairResultDialog = true
                            } ?: run {
                                unpairResult = "❌ Bluetooth service not available.\n\nPlease check Bluetooth permissions."
                                showUnpairResultDialog = true
                            }
                        },
                        colors = androidx.compose.material3.ButtonDefaults.buttonColors(
                            containerColor = androidx.compose.ui.graphics.Color(0xFFFF5722)
                        )
                    ) {
                        androidx.compose.material3.Text("Yes, Forget All", fontWeight = androidx.compose.ui.text.font.FontWeight.Bold)
                    }
                },
                dismissButton = {
                    androidx.compose.material3.OutlinedButton(
                        onClick = { showUnpairConfirmDialog = false }
                    ) {
                        androidx.compose.material3.Text("Cancel")
                    }
                }
            )
        }

        // Unpair Result Dialog
        if (showUnpairResultDialog) {
            androidx.compose.material3.AlertDialog(
                onDismissRequest = { showUnpairResultDialog = false },
                title = { androidx.compose.material3.Text("Devices Removed") },
                text = { androidx.compose.material3.Text(unpairResult) },
                confirmButton = {
                    androidx.compose.material3.TextButton(
                        onClick = { showUnpairResultDialog = false }
                    ) {
                        androidx.compose.material3.Text("OK")
                    }
                }
            )
        }

        // Long Press Speed Dialog
        if (showLongPressSpeedDialog) {
            LongPressSpeedDialog(
                currentSpeed = longPressSpeed,
                onSpeedSelected = { newSpeed ->
                    longPressSpeed = newSpeed
                    prefsManager.saveLongPressSpeed(newSpeed)
                },
                onDismiss = { showLongPressSpeedDialog = false }
            )
        }
    }
}

@OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class)
@Composable
fun DatabaseViewerScreen(
    repository: FQCRepository,
    onBack: () -> Unit
) {
    val scope = rememberCoroutineScope()
    val bgColor = Color(0xFF212121)
    val surfaceColor = Color(0xFF2B2B2B)
    val accentColor = Color(0xFFFFC107)
    val textColor = Color.White
    val dividerColor = Color(0xFF424242)

    var isLoading by remember { mutableStateOf(true) }
    var expandedSections by remember { mutableStateOf<Set<String>>(setOf()) }

    // Data state
    var devices by remember { mutableStateOf<List<Device>>(emptyList()) }
    var operators by remember { mutableStateOf<List<Operator>>(emptyList()) }
    var testSessions by remember { mutableStateOf<List<com.example.fqcapp.data.entities.TestSession>>(emptyList()) }
    var frequencyTests by remember { mutableStateOf<List<com.example.fqcapp.data.entities.FrequencyTest>>(emptyList()) }
    var songTests by remember { mutableStateOf<List<com.example.fqcapp.data.entities.SongTest>>(emptyList()) }
    var fqcRecords by remember { mutableStateOf<List<com.example.fqcapp.data.entities.FQCRecord>>(emptyList()) }
    var driverPairingRecords by remember { mutableStateOf<List<com.example.fqcapp.data.entities.DriverPairingRecord>>(emptyList()) }
    var macIdCache by remember { mutableStateOf<List<com.example.fqcapp.data.entities.MacIdCache>>(emptyList()) }
    var workflowEvents by remember { mutableStateOf<List<com.example.fqcapp.data.entities.DeviceWorkflow>>(emptyList()) }

    LaunchedEffect(Unit) {
        scope.launch {
            try {
                withContext(Dispatchers.IO) {
                    // Load all data
                    devices = repository.getAllDevices().first()
                    operators = repository.getAllOperators().first()
                    testSessions = repository.getAllTestSessions()
                    frequencyTests = repository.getAllFrequencyTests()
                    songTests = repository.getAllSongTests()
                    fqcRecords = repository.getAllFQCRecords()
                    driverPairingRecords = repository.getAllDriverPairingRecords()
                    macIdCache = repository.getAllCachedMacIds()
                    // Load workflow events (get all, then sort by timestamp)
                    workflowEvents = repository.getAllWorkflowEvents().sortedByDescending { it.timestamp }

                    // Debug: Log loaded FQC records
                    android.util.Log.d("DatabaseViewer", "📊 Loaded ${fqcRecords.size} FQC records")
                    fqcRecords.forEachIndexed { index, record ->
                        android.util.Log.d("DatabaseViewer", "📊 FQC Record #${index + 1} (ID: ${record.fqcId}):")
                        android.util.Log.d("DatabaseViewer", "📊   Serial: '${record.serialNumber}'")
                        android.util.Log.d("DatabaseViewer", "📊   Operator: '${record.operatorName}'")
                        android.util.Log.d("DatabaseViewer", "📊   Final Quality Type: '${record.finalQualityType}'")
                        android.util.Log.d("DatabaseViewer", "📊   Criteria: '${record.criteriaChecked}'")
                        android.util.Log.d("DatabaseViewer", "📊   Entry: '${record.entryTimestamp}'")
                        android.util.Log.d("DatabaseViewer", "📊   Exit: '${record.exitTimestamp}'")
                        android.util.Log.d("DatabaseViewer", "📊   Time: '${record.totalTimeSpent}'")
                        android.util.Log.d("DatabaseViewer", "📊   Iteration: ${record.iterationNumber}")
                        android.util.Log.d("DatabaseViewer", "📊   FQC Type: '${record.fqcType}'")
                    }
                }
                isLoading = false
            } catch (e: Exception) {
                android.util.Log.e("DatabaseViewer", "Error loading database", e)
                isLoading = false
            }
        }
    }

    Scaffold(
        containerColor = bgColor,
        topBar = {
            TopAppBar(
                title = { Text("Database Viewer", color = textColor) },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(
                            imageVector = Icons.Filled.ArrowBack,
                            contentDescription = "Back",
                            tint = textColor
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = surfaceColor,
                    titleContentColor = textColor,
                    navigationIconContentColor = textColor
                )
            )
        }
    ) { padding ->
        if (isLoading) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(padding),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator(color = accentColor)
            }
        } else {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(padding)
                    .verticalScroll(rememberScrollState())
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                // Summary Card
                DatabaseSummaryCard(
                    devices = devices,
                    operators = operators,
                    testSessions = testSessions,
                    frequencyTests = frequencyTests,
                    songTests = songTests,
                    fqcRecords = fqcRecords,
                    driverPairingRecords = driverPairingRecords,
                    macIdCache = macIdCache,
                    workflowEvents = workflowEvents,
                    surfaceColor = surfaceColor,
                    textColor = textColor
                )

                // Devices Section
                DatabaseSection(
                    title = "Devices",
                    count = devices.size,
                    isExpanded = expandedSections.contains("devices"),
                    onExpandToggle = {
                        expandedSections = if (expandedSections.contains("devices")) {
                            expandedSections - "devices"
                        } else {
                            expandedSections + "devices"
                        }
                    },
                    surfaceColor = surfaceColor,
                    textColor = textColor,
                    accentColor = accentColor
                ) {
                    if (devices.isEmpty()) {
                        Text("No devices found", color = textColor.copy(alpha = 0.6f))
                    } else {
                        devices.forEach { device ->
                            DeviceCard(device, surfaceColor, textColor)
                        }
                    }
                }

                // Test Sessions Section
                DatabaseSection(
                    title = "Test Sessions",
                    count = testSessions.size,
                    isExpanded = expandedSections.contains("sessions"),
                    onExpandToggle = {
                        expandedSections = if (expandedSections.contains("sessions")) {
                            expandedSections - "sessions"
                        } else {
                            expandedSections + "sessions"
                        }
                    },
                    surfaceColor = surfaceColor,
                    textColor = textColor,
                    accentColor = accentColor
                ) {
                    if (testSessions.isEmpty()) {
                        Text("No sessions found", color = textColor.copy(alpha = 0.6f))
                    } else {
                        testSessions.forEach { session ->
                            TestSessionCard(session, surfaceColor, textColor)
                        }
                    }
                }

                // Frequency Tests Section
                DatabaseSection(
                    title = "Frequency Tests",
                    count = frequencyTests.size,
                    isExpanded = expandedSections.contains("frequency"),
                    onExpandToggle = {
                        expandedSections = if (expandedSections.contains("frequency")) {
                            expandedSections - "frequency"
                        } else {
                            expandedSections + "frequency"
                        }
                    },
                    surfaceColor = surfaceColor,
                    textColor = textColor,
                    accentColor = accentColor
                ) {
                    if (frequencyTests.isEmpty()) {
                        Text("No frequency tests found", color = textColor.copy(alpha = 0.6f))
                    } else {
                        frequencyTests.forEach { test ->
                            FrequencyTestCard(test, surfaceColor, textColor)
                        }
                    }
                }

                // Song Tests Section
                DatabaseSection(
                    title = "Song Tests",
                    count = songTests.size,
                    isExpanded = expandedSections.contains("songs"),
                    onExpandToggle = {
                        expandedSections = if (expandedSections.contains("songs")) {
                            expandedSections - "songs"
                        } else {
                            expandedSections + "songs"
                        }
                    },
                    surfaceColor = surfaceColor,
                    textColor = textColor,
                    accentColor = accentColor
                ) {
                    if (songTests.isEmpty()) {
                        Text("No song tests found", color = textColor.copy(alpha = 0.6f))
                    } else {
                        // Group song tests by serial number and iteration number
                        val groupedTests = songTests.groupBy { "${it.serialNumber}_${it.iterationNumber}" }
                        groupedTests.values.forEach { tests ->
                            // Find overall review (isOverallResult = true)
                            val overallReview = tests.find { it.isOverallResult }
                            val individualSongs = tests.filter { !it.isOverallResult }.sortedByDescending { it.timestamp }

                            if (overallReview != null) {
                                // Display overall review with all details and individual songs
                                SongTestCard(
                                    overallReview = overallReview,
                                    individualSongs = individualSongs,
                                    surfaceColor = surfaceColor,
                                    textColor = textColor
                                )
                                Spacer(modifier = Modifier.height(8.dp))
                            } else {
                                // If no overall review, just show individual songs
                                individualSongs.forEach { song ->
                                    IndividualSongCard(song, surfaceColor, textColor)
                                    Spacer(modifier = Modifier.height(4.dp))
                                }
                            }
                        }
                    }
                }

                // FQC Records Section
                DatabaseSection(
                    title = "FQC Records",
                    count = fqcRecords.size,
                    isExpanded = expandedSections.contains("fqc"),
                    onExpandToggle = {
                        expandedSections = if (expandedSections.contains("fqc")) {
                            expandedSections - "fqc"
                        } else {
                            expandedSections + "fqc"
                        }
                    },
                    surfaceColor = surfaceColor,
                    textColor = textColor,
                    accentColor = accentColor
                ) {
                    if (fqcRecords.isEmpty()) {
                        Text("No FQC records found", color = textColor.copy(alpha = 0.6f))
                    } else {
                        fqcRecords.forEach { record ->
                            FQCRecordCard(record, surfaceColor, textColor)
                        }
                    }
                }

                // Driver Pairing Records Section
                DatabaseSection(
                    title = "Driver Pairing Records",
                    count = driverPairingRecords.size,
                    isExpanded = expandedSections.contains("driverPairing"),
                    onExpandToggle = {
                        expandedSections = if (expandedSections.contains("driverPairing")) {
                            expandedSections - "driverPairing"
                        } else {
                            expandedSections + "driverPairing"
                        }
                    },
                    surfaceColor = surfaceColor,
                    textColor = textColor,
                    accentColor = accentColor
                ) {
                    if (driverPairingRecords.isEmpty()) {
                        Text("No driver pairing records found", color = textColor.copy(alpha = 0.6f))
                    } else {
                        driverPairingRecords.forEach { record ->
                            DriverPairingRecordCard(record, surfaceColor, textColor)
                        }
                    }
                }

                // Workflow Events Section (NEW - Shows audit trail)
                DatabaseSection(
                    title = "Workflow Events (Audit Trail)",
                    count = workflowEvents.size,
                    isExpanded = expandedSections.contains("workflow"),
                    onExpandToggle = {
                        expandedSections = if (expandedSections.contains("workflow")) {
                            expandedSections - "workflow"
                        } else {
                            expandedSections + "workflow"
                        }
                    },
                    surfaceColor = surfaceColor,
                    textColor = textColor,
                    accentColor = accentColor
                ) {
                    if (workflowEvents.isEmpty()) {
                        Text("No workflow events found", color = textColor.copy(alpha = 0.6f))
                    } else {
                        // Group by device serial for easier viewing
                        val groupedByDevice = workflowEvents.groupBy { it.serialNumber }
                        groupedByDevice.forEach { (serial, events) ->
                            Text(
                                "Device: $serial (${events.size} events)",
                                color = accentColor,
                                fontWeight = FontWeight.Bold,
                                fontSize = 13.sp,
                                modifier = Modifier.padding(vertical = 8.dp)
                            )
                            events.forEach { event ->
                                WorkflowEventCard(event, surfaceColor, textColor)
                            }
                            Spacer(modifier = Modifier.height(8.dp))
                        }
                    }
                }

                // Operators Section
                DatabaseSection(
                    title = "Operators",
                    count = operators.size,
                    isExpanded = expandedSections.contains("operators"),
                    onExpandToggle = {
                        expandedSections = if (expandedSections.contains("operators")) {
                            expandedSections - "operators"
                        } else {
                            expandedSections + "operators"
                        }
                    },
                    surfaceColor = surfaceColor,
                    textColor = textColor,
                    accentColor = accentColor
                ) {
                    if (operators.isEmpty()) {
                        Text("No operators found", color = textColor.copy(alpha = 0.6f))
                    } else {
                        operators.forEach { operator ->
                            OperatorCard(operator, surfaceColor, textColor)
                        }
                    }
                }

                // MAC ID Cache Section
                DatabaseSection(
                    title = "MAC ID Cache",
                    count = macIdCache.size,
                    isExpanded = expandedSections.contains("mac"),
                    onExpandToggle = {
                        expandedSections = if (expandedSections.contains("mac")) {
                            expandedSections - "mac"
                        } else {
                            expandedSections + "mac"
                        }
                    },
                    surfaceColor = surfaceColor,
                    textColor = textColor,
                    accentColor = accentColor
                ) {
                    if (macIdCache.isEmpty()) {
                        Text("No MAC ID cache entries", color = textColor.copy(alpha = 0.6f))
                    } else {
                        macIdCache.forEach { cache ->
                            MacIdCacheCard(cache, surfaceColor, textColor)
                        }
                    }
                }
            }
        }
    }
}

