                Spacer(modifier = Modifier.height(4.dp))
            } else {
                Text("Final Headphone Quality: Not Set", color = textColor.copy(alpha = 0.6f), fontSize = 12.sp, fontStyle = FontStyle.Italic)
                Spacer(modifier = Modifier.height(4.dp))
            }

            // Criteria Checked
            if (record.criteriaChecked.isNotBlank() && record.criteriaChecked != "[]") {
                Spacer(modifier = Modifier.height(4.dp))
                Text("Criteria Checked:", color = textColor.copy(alpha = 0.9f), fontSize = 11.sp, fontWeight = FontWeight.Medium)
                Text(record.criteriaChecked, color = textColor.copy(alpha = 0.8f), fontSize = 11.sp)
            }

            // Legacy fields (for backward compatibility)
            if (record.fqcType.isNotBlank()) {
                Spacer(modifier = Modifier.height(4.dp))
                Text("Type: ${record.fqcType}", color = textColor.copy(alpha = 0.7f), fontSize = 11.sp)
            }
            if (record.timestamp.isNotBlank()) {
                Text("Timestamp: ${record.timestamp}", color = textColor.copy(alpha = 0.7f), fontSize = 11.sp)
            }
        }
    }
}

