// Attach change listeners directly to grid inputs (more reliable than frappe events for Select fields)
function attach_grid_change_listeners(frm) {
    setTimeout(function() {
        if (!frm.fields_dict['pcb_iqc_data_enter'] || !frm.fields_dict['pcb_iqc_data_enter'].grid) return;
        let grid = frm.fields_dict['pcb_iqc_data_enter'].grid;
        let wrapper = grid.wrapper;
        if (!wrapper) return;
        
        // Remove old listeners first
        wrapper.off('change.pcb_iqc_capture');
        
        // CRITICAL FIX: Listen for change events and read DIRECTLY from DOM element value
        wrapper.on('change.pcb_iqc_capture', 'select, input', function(e) {
            let $target = $(e.target);
            let fieldname = $target.attr('data-fieldname') || $target.attr('name');
            let fieldtype = $target.attr('data-fieldtype') || '';
            let new_value = $target.val(); // Read DIRECTLY from DOM element
            
            console.log('🔔 Grid change detected - Field:', fieldname, 'New value:', new_value, 'Type:', fieldtype);
            
            // Get the row
            let $row = $target.closest('.grid-row');
            if (!$row.length) return;
            let row_name = $row.attr('data-name');
            if (!row_name) return;
            
            // CRITICAL: Get the grid row object to update
            let grid_row = null;
            if (grid.grid_rows && grid.grid_rows.length > 0) {
                grid_row = grid.grid_rows[0];
            }
            if (!grid_row || !grid_row.doc) return;
            
            // CRITICAL: Update the grid row doc IMMEDIATELY with the DOM value
            // This ensures we capture the actual selected value, not stale locals data
            if (fieldname && new_value !== undefined && new_value !== null) {
                // Normalize select values
                let normalized_value = new_value;
                if (fieldname.includes('status')) {
                    let s = String(new_value).trim();
                    if (s) {
                        let upper = s.toUpperCase();
                        if (upper === 'PENDING') normalized_value = 'Pending';
                        else if (upper === 'PASS') normalized_value = 'Pass';
                        else if (upper === 'FAIL') normalized_value = 'Fail';
                        else normalized_value = s;
                    }
                }
                
                // Update grid row doc directly
                grid_row.doc[fieldname] = normalized_value;
                
                // Also update locals if available (for Frappe's internal consistency)
                if (locals['PCB IQC Data Enter'] && locals['PCB IQC Data Enter'][row_name]) {
                    locals['PCB IQC Data Enter'][row_name][fieldname] = normalized_value;
                }
                
                console.log('✓ Updated', fieldname, 'to', normalized_value, 'in grid row doc');
            }
            
            // Now capture with updated values (with small delay to ensure all updates are done)
            setTimeout(function() {
                // Re-read from grid row doc (now contains the latest DOM value)
                let latest_row = null;
                if (grid_row && grid_row.doc) {
                    latest_row = safe_clone_object(grid_row.doc);
                } else if (locals['PCB IQC Data Enter'] && locals['PCB IQC Data Enter'][row_name]) {
                    latest_row = safe_clone_object(locals['PCB IQC Data Enter'][row_name]);
                }
                
                if (latest_row) {
                    frm.__pcb_iqc_last_data_enter_row = latest_row;
                    frm.__pcb_iqc_last_data_enter_serial = latest_row.pcb_serial_no ? String(latest_row.pcb_serial_no).trim() : null;
                    console.log('✓ Captured PCB IQC Data Enter data is', {
                        pts1_status: latest_row.pts1_status || 'null',
                        pts2_status: latest_row.pts2_status || 'null',
                        pts3_status: latest_row.pts3_status || 'null',
                        overall_status: latest_row.overall_status || 'null',
                        serial: frm.__pcb_iqc_last_data_enter_serial
                    });
                    
                    // CRITICAL: Mark form dirty to show Update button
                    frm.dirty();
                }
            }, 50); // Small delay to ensure all field updates are processed
        });
        
        console.log('✓ Attached grid change listeners to PCB IQC Data Enter');
    }, 200);
}

// Helper function to safely clone an object (avoids circular reference errors)
function safe_clone_object(obj) {
    if (!obj) return null;
    try {
        // Try JSON.stringify first (fastest)
        return JSON.parse(JSON.stringify(obj));
    } catch (e) {
        // If circular reference error, manually copy only the fields we need
        if (e.message && e.message.indexOf('circular') !== -1) {
            let cloned = {};
            // Copy only the fields we actually use
            let fields_to_copy = [
                'pcb_serial_no', 'item_code', 'overall_status', 'iqc_date',
                'pts1_status', 'pts1_date', 'pts2_status', 'pts2_date',
                'pts3_status', 'pts3_date', 'dominant_channel', 'max_value', 'remarks'
            ];
            for (let i = 0; i < fields_to_copy.length; i++) {
                let field = fields_to_copy[i];
                if (obj.hasOwnProperty(field)) {
                    cloned[field] = obj[field];
                }
            }
            return cloned;
        }
        // For other errors, return null
        return null;
    }
}

// Helper function to get clean item_code value from parent form
function get_parent_item_code(frm) {
    // Try multiple possible field names for PCB Item
    let possible_fields = ['pcb', 'table_jqbb', 'item_code', 'pcb_item'];
    let parent_item_code = null;
    
    for (let i = 0; i < possible_fields.length; i++) {
        let field_name = possible_fields[i];
        if (frm.doc[field_name]) {
            let val = frm.doc[field_name];
            if (typeof val === 'string' && val.trim()) {
                parent_item_code = val.trim();
                break;
            } else if (typeof val === 'object' && val !== null) {
                if (Array.isArray(val)) {
                    // If it's an array, get first element's name
                    if (val.length > 0) {
                        let first = val[0];
                        if (typeof first === 'object' && first.name) {
                            parent_item_code = first.name;
                            break;
                        } else if (typeof first === 'string') {
                            parent_item_code = first;
                            break;
                        }
                    }
                } else {
                    // If it's an object, get name property
                    if (val.name) {
                        parent_item_code = val.name;
                        break;
                    }
                }
            }
        }
    }
    
    // If still not found, try to get from first child row's item_code if it's valid
    if (!parent_item_code && frm.doc.table_jqbb && frm.doc.table_jqbb.length > 0) {
        for (let i = 0; i < frm.doc.table_jqbb.length; i++) {
            let row = frm.doc.table_jqbb[i];
            if (row.item_code && typeof row.item_code === 'string' && row.item_code.indexOf('[object Object]') === -1) {
                parent_item_code = row.item_code;
                break;
            }
        }
    }
    
    return parent_item_code || '';
}

// Helper function to clean ALL item_code values in pcb table (reusable)
function clean_all_item_codes(frm) {
    let pcb_table_field = 'table_jqbb';
    if (!frm.doc[pcb_table_field] || frm.doc[pcb_table_field].length === 0) {
        console.log('  No rows in pcb table to clean');
        return 0;
    }
    
    // Get clean parent item_code value ONCE
    let parent_item_code = get_parent_item_code(frm);
    console.log(`  Parent item_code value: "${parent_item_code}"`);
    
    let cleaned_count = 0;
    for (let i = 0; i < frm.doc[pcb_table_field].length; i++) {
        let row = frm.doc[pcb_table_field][i];
        let item_code_val = row.item_code;
        let current_str = String(item_code_val || '');
        let is_bad = current_str.indexOf('[object Object]') !== -1 || 
                    (typeof item_code_val === 'object' && item_code_val !== null) ||
                    Array.isArray(item_code_val) ||
                    !item_code_val;
        
        if (is_bad) {
            // Use parent item_code value
            let clean_val = parent_item_code;
            
            console.log(`  Row ${i+1}: Cleaning item_code "${current_str}" (type: ${typeof item_code_val}) -> "${clean_val}"`);
            
            // CRITICAL: Set directly on row object
            row.item_code = clean_val;
            
            // Also set via frappe.model.set_value
            try {
                frappe.model.set_value(row.doctype, row.name, 'item_code', clean_val);
                cleaned_count++;
            } catch (e) {
                console.error(`  Error cleaning item_code row ${i+1}:`, e);
            }
        } else {
            // Even if it looks OK, verify it matches parent (optional - only if parent exists)
            if (parent_item_code && current_str !== parent_item_code) {
                // Optionally normalize to parent value for consistency
                // Uncomment if you want all rows to have the same item_code as parent
                // row.item_code = parent_item_code;
                // frappe.model.set_value(row.doctype, row.name, 'item_code', parent_item_code);
            }
        }
    }
    
    if (cleaned_count > 0) {
        frm.refresh_field(pcb_table_field);
        console.log(`✓ Cleaned ${cleaned_count} item_code values`);
    } else {
        console.log(`✓ All item_code values are already clean`);
    }
    return cleaned_count;
}

// Helper function to read status values directly from DOM select elements (most reliable)
