        if (!frm.fields_dict['pcb_iqc_data_enter'] || !frm.fields_dict['pcb_iqc_data_enter'].grid) return null;
        let grid = frm.fields_dict['pcb_iqc_data_enter'].grid;
        let wrapper = grid.wrapper;
        if (!wrapper) return null;

        // Find the select element for this field
        let $select = wrapper.find('select[data-fieldname="' + fieldname + '"]');
        if ($select.length) {
            let value = $select.val();
            if (value) {
                // Normalize
                let s = String(value).trim();
                let upper = s.toUpperCase();
                if (upper === 'PENDING') return 'Pending';
                if (upper === 'PASS') return 'Pass';
                if (upper === 'FAIL') return 'Fail';
                return s;
            }
        }
    } catch (e) {
        console.error('Error reading from DOM:', e);
    }
    return null;
}

