                }
                Text(
                    text = record.overallResult,
                    color = if (record.overallResult == "PASS") Color(0xFF4CAF50) else Color(0xFFFF5722),
                    fontWeight = FontWeight.Bold,
                    fontSize = 12.sp
                )
            }

            Divider(modifier = Modifier.padding(vertical = 8.dp), color = textColor.copy(alpha = 0.3f))

