            Text("Serial: ${record.serialNumber}", color = textColor.copy(alpha = 0.9f), fontSize = 12.sp, fontWeight = FontWeight.Medium)
            Text("Operator: ${record.operatorName}", color = textColor.copy(alpha = 0.9f), fontSize = 12.sp, fontWeight = FontWeight.Medium)
            if (record.iterationNumber > 0) {
                Text("Iteration: ${record.iterationNumber}", color = textColor.copy(alpha = 0.9f), fontSize = 12.sp, fontWeight = FontWeight.Medium)
            }

            Spacer(modifier = Modifier.height(4.dp))

            // Entry/Exit Timestamps and Total Time
            if (record.entryTimestamp.isNotBlank()) {
                Text("Entry: ${record.entryTimestamp}", color = textColor.copy(alpha = 0.8f), fontSize = 11.sp)
            }
            if (record.exitTimestamp.isNotBlank()) {
