            }
            if (record.totalTimeSpent.isNotBlank() && record.totalTimeSpent != "00:00:00") {
                Text("Time Spent: ${record.totalTimeSpent}", color = textColor.copy(alpha = 0.8f), fontSize = 11.sp, fontWeight = FontWeight.Medium)
            }

            Spacer(modifier = Modifier.height(4.dp))

            // Final Headphone Quality (also displayed in header, but show here again for clarity)
            if (record.finalQualityType.isNotBlank()) {
                Text(
                    "Final Headphone Quality: ${record.finalQualityType}",
                    color = when (record.finalQualityType.uppercase()) {
                        "REVIEWER" -> Color(0xFF4CAF50)
                        "CUSTOMER" -> Color(0xFFFFC107)
                        "INTERNATIONAL" -> Color(0xFF2196F3)
                        "MARKETING" -> Color(0xFF9C27B0)
